#!/usr/bin/env python3
"""Generate evidence-backed 1280x720 slides and narration scripts for Hack Apertus video."""
from pathlib import Path
from html import escape

here=Path(__file__).resolve().parent
slides=[
 dict(tag="MERGEPROOF  ·  TRACK 2B",title="What does a merged PR<br><em>actually prove?</em>",sub="Evidence-first multilingual contribution dossiers, powered by the open Apertus 1.5 model.",bullets=["Public GitHub facts.","Apertus explanations.","Independent grounding controls."],side="EVIDENCE BEFORE ELOQUENCE",voice="What does a merged pull request actually prove? This is MergeProof, an open-source, multilingual contribution dossier built with Apertus 1.5. We separate verified repository facts from explanations generated by AI."),
 dict(tag="01  /  THE REAL EXAMPLE",title="One real contribution.<br><em>Four verified facts.</em>",sub="BossConsole pull request number 1681 — collected directly from public GitHub evidence.",bullets=["Merge status: MERGED","Changed files: 2  ·  Linked issue: #1632","Matching release: BOSS v9.5.25"],side="NO PAYMENT CLAIMS",voice="Our example uses real pull request number 1681 in BossConsole. GitHub confirms it is merged, with two changed files, linked issue 1632, and a matching release reference. MergeProof does not infer payments or business impact from a merge."),
 dict(tag="02  /  PUBLIC DEMO",title="Inspectable evidence.<br><em>Not a mockup.</em>",sub="A public recorded-evidence viewer backed by a committed real model evaluation.",bullets=["Open-source browser demo","Switch between languages","Inspect evidence references"],side="RECORDED EVIDENCE · NOT LIVE INFERENCE",voice="Here is the public demonstration interface. It displays source-linked evidence and language-specific output using a real recorded Apertus evaluation. We label it correctly as a recorded demonstration, not a live hosted inference service.",image=True),
 dict(tag="03  /  TRUST BOUNDARY",title="GitHub states facts.<br><em>Apertus explains.</em>",sub="The language model can assist understanding without rewriting source-of-truth metadata.",bullets=["Bounded structured evidence packet","Claim-level evidence_refs must resolve","Unsupported summaries replaced by factual fallback"],side="NO HALLUCINATED MERGE STATUS",voice="The system collects GitHub facts first, then sends a bounded structured packet to Apertus. Every generated claim needs a valid evidence reference. Unsupported or invented references are rejected, and merge status always comes from GitHub."),
 dict(tag="04  /  REAL APERTUS TEST",title="Four languages.<br><em>One consistent truth.</em>",sub="Real local Apertus 1.5, eight-billion-parameter community MLX run, not claimed to be CSCS inference.",bullets=["English  ·  German  ·  French  ·  Russian","MERGED invariant held in 4 of 4","Zero invalid evidence references accepted"],side="MEDIAN MODEL LATENCY 15.44s",voice="We evaluated local Apertus 1.5 eight B in English, German, French and Russian. Across all four languages, merge status stayed correct and the sanitization layer accepted zero invalid evidence references. The median local model latency was 15.44 seconds."),
 dict(tag="05  /  REPRODUCIBLE ENGINEERING",title="Measured performance.<br><em>Clear limitations.</em>",sub="Five independent real-world public-GitHub evidence collections.",bullets=["Stable facts across 5 of 5 runs","Evidence packet: 1,060 bytes","Collection median: 1.128 seconds"],side="NO INVENTED HOSTED METRICS",voice="Five independent GitHub evidence collections returned stable factual results, each with a 1,060 byte evidence packet. Median collection time was about 1.13 seconds. We report local model latency separately from GitHub fetch latency."),
 dict(tag="06  /  OPEN AND SOVEREIGN",title="Built to inspect.<br><em>Built to reproduce.</em>",sub="Source code, tests, model-run artifacts and demonstration are publicly available.",bullets=["Apertus provider can be changed","No proprietary model API required","Open source under Apache-2.0"],side="HACK APERTUS 2026  ·  MERGEPROOF",voice="MergeProof uses an open model and a configurable inference provider, so it can run on local or sovereign infrastructure. The code, evaluation artifacts and public demonstration are all open for inspection. Thank you for reviewing MergeProof.")
]
css="""*{box-sizing:border-box}html,body{width:1280px;height:720px;margin:0;background:#071923;color:#f4f8f8;font-family:-apple-system,Arial,sans-serif;overflow:hidden}
body{padding:56px 75px;position:relative;background:radial-gradient(circle at 100% 0%,#174c55 0%,#0b2b37 30%,#071923 72%)}
body::after{content:'';position:absolute;right:-170px;bottom:-280px;width:570px;height:570px;border:1px solid #245a64;border-radius:50%;pointer-events:none}
.kicker{font-size:18px;color:#64e7d0;letter-spacing:4px;font-weight:800;text-transform:uppercase}
h1{font-size:56px;line-height:1.09;letter-spacing:-2px;max-width:1020px;margin:33px 0 18px}
h1 em{color:#6ee0c5;font-style:normal}
.lead{font-size:23px;line-height:1.45;max-width:1000px;color:#bbd3d8}
ul{list-style:none;padding:0;margin:30px 0 0}
li{font-size:22px;margin:15px 0;color:#e4f6f4}
li::before{content:'✓';color:#5de4cd;font-weight:800;margin-right:14px}
.bottom{position:absolute;bottom:45px;left:75px;right:75px;border-top:1px solid #315762;padding-top:15px;display:flex;justify-content:space-between;color:#7baeb2;font-size:16px;letter-spacing:1px}
.side{color:#55cab8;font-size:16px;font-weight:750}
.preview{position:absolute;right:65px;top:200px;width:600px;height:382px;object-fit:cover;object-position:top left;border:2px solid #518e92;box-shadow:0 18px 40px rgba(0,0,0,.45)}
.has-image h1{font-size:44px;max-width:580px}
.has-image .lead{font-size:21px;max-width:500px}
.has-image ul{max-width:555px}
.has-image li{font-size:19px}
"""
for i,slide in enumerate(slides):
 items="".join("<li>"+escape(s)+"</li>" for s in slide['bullets'])
 image='<img class="preview" src="live-demo.png"/>' if slide.get("image") else ""
 markup=f'''<!doctype html><html><head><meta charset="utf-8"><style>{css}</style></head>
 <body class="{'has-image' if slide.get('image') else ''}"><div class="kicker">{escape(slide['tag'])}</div>
 <h1>{slide['title']}</h1><p class="lead">{escape(slide['sub'])}</p><ul>{items}</ul>{image}
 <div class="bottom"><span>MERGEPROOF / HACK APERTUS 2026</span><span class="side">{escape(slide['side'])}</span></div></body></html>'''
 (here/f"slide-{i:02}.html").write_text(markup)
 (here/f"narration-{i:02}.txt").write_text(slide["voice"]+"\n")
print("SCENES",len(slides),"narration_words",sum(len(x["voice"].split()) for x in slides))
